contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes an amount to send to play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure the test contract has sufficient balance to send `amount` if needed
        require(address(this).balance >= amount);

        // read the bank address before the call
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;

        bool reverted;
        // attempt to call play with provided amount
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read the bank address after the call
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;

        // If amount != TICKET_AMOUNT, the call must revert. If amount == TICKET_AMOUNT, the call must not change the bank address.
        assert(((amount != 10) && reverted) || ((amount == 10) && (bankAfter == bankBefore)));
    }

    // allow contract to receive Ether so tests can fund it
    receive() external payable {}
}

